(async()=>{if(new URLSearchParams(location.search).get('profile')!=='structure-slope-check')return;while(!window.EmberQA)await new Promise(r=>setTimeout(r,100));const q=EmberQA,D=SurvivalData,W=EmberTerrain,T=THREE;document.getElementById('welcome').hidden=true;q.setPlaying(false);const report=document.createElement('pre');report.id='structure-report';report.style='position:fixed;top:12px;left:12px;background:white;color:#234;padding:12px;z-index:200';document.body.append(report);const result={},check=(k,v)=>{result[k]=!!v;report.textContent=JSON.stringify(result,null,2);if(!v)throw Error(k);};try{q.apply({...D.fresh(),inventory:{hammer:1},hand:'hammer',blueprints:['house'],automaticTime:false});let p;outer:for(let z=10;z<250;z+=4)for(let x=-160;x<160;x+=4){const v={x,z,y:W.ground(x,z)},fit=q.world.tentFrame({...v,type:'house'});if(fit.angle>5&&fit.angle<18&&!q.canBuild(v)){p=v;break outer;}}check('houseSlopeFound',p);Object.assign(q.state,{x:p.x,z:p.z+5,y:W.ground(p.x,p.z+5)});for(const type of ['house','campfire']){let pos=p;if(type==='campfire'){pos=null;outer:for(let z=p.z+8;z<p.z+20;z++)for(let x=p.x-6;x<p.x+6;x++){const v={x,z,y:W.ground(x,z)};if(!q.slopedPlacement(v,type)){pos=v;break outer;}}}check(type+'Placement',pos);const r=D.recipes.find(r=>r.id===type);q.state.piles.push({...pos,id:'pile-'+type,items:{...r.cost}});q.craft('pile-'+type,type);const job=q.state.jobs.find(v=>v.type===type);check(type+'Craft',job);q.work(job,r.time);const s=q.state.structures.find(v=>v.type===type);check(type+'Completed',s?.progress===1);const mesh=q.world.dynamic.children.find(g=>Math.abs(g.position.x-s.x)<.001&&Math.abs(g.position.z-s.z)<.001&&g.children.length>5);check(type+'MeshAligned',mesh&&mesh.quaternion.angleTo(q.world.tentFrame(s).rotation)<.00001);if(type==='campfire')s.lit=true;}q.syncObjects();const house=q.state.structures.find(s=>s.type==='house'),fit=q.world.tentFrame(house),local=(x,y,z)=>new T.Vector3(x,y,z).applyQuaternion(fit.rotation).add(new T.Vector3(house.x,fit.y,house.z));const inside=local(0,.3,0);Object.assign(q.state,{x:inside.x,y:inside.y,z:inside.z});check('insideRotatedHouse',q.inHouse());check('floorMatches',Math.abs(q.world.floor(inside.x,inside.z,inside.y,q.state)-inside.y)<.001);const door=local(0,.3,3.2),wall=local(3.7,.3,0);check('entranceOpen',!q.world.blocked(door.x,door.z,door.y,q.state));check('wallSolid',q.world.blocked(wall.x,wall.z,wall.y,q.state));const fire=q.state.structures.find(s=>s.type==='campfire');q.state.checkpoint={id:fire.id,x:fire.x,y:fire.y,z:fire.z};check('save',q.saveSlot(18));q.loadSlot(18);q.setPlaying(false);check('restoreBoth',q.state.structures.length===2);q.close(false);q.camera.position.set(p.x+11,p.y+7,p.z+17);q.camera.lookAt(p.x,p.y+2,p.z+3);q.sky.update(q.state,0,true);q.renderer.render(q.scene,q.camera);result.complete=true;report.textContent=JSON.stringify(result,null,2);const hide=document.createElement('button');hide.textContent='確認表示を閉じる';hide.style='position:fixed;top:12px;right:12px;z-index:201';hide.onclick=()=>{report.hidden=true;hide.remove();};document.body.append(hide);}catch(e){report.textContent+='\nFAIL '+e.stack;}})();
